699:   _menuCurtain() {
700:     const w = 512, h = 512, c = document.createElement('canvas');
701:     c.width = w; c.height = h;
702:     const x = c.getContext('2d');
703:     x.fillStyle = '#3a1114'; x.fillRect(0, 0, w, h);
704:     for (let i = 0; i < 64; i++) {
705:       const px = (i / 64) * w;
706:       const g = x.createLinearGradient(px - 10, 0, px + 10, 0);
707:       g.addColorStop(0, 'rgba(0,0,0,.45)');
708:       g.addColorStop(.5, 'rgba(140,45,40,.22)');
709:       g.addColorStop(1, 'rgba(0,0,0,.45)');
710:       x.fillStyle = g; x.fillRect(px - 10, 0, 20, h);
711:     }
712:     x.fillStyle = 'rgba(255,210,150,.08)';
713:     for (let i = 0; i < 60; i++) x.beginPath(), x.arc(rand() * w, rand() * h, 1 + rand() * 3, 0, 7), x.fill();
714:     return finish(c, 1.5, 1);
715:   }
