117: export function floorTexture() {
118:   const w = 512, h = 512, c = canvas(w, h), x = c.getContext('2d');
119:   const n = 4, s = w / n;
120:   for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
121:     const dark = (i + j) % 2 === 0;
122:     x.fillStyle = dark ? '#2b2822' : '#c9bda2';
123:     x.fillRect(i * s, j * s, s, s);
124:     // tile edge bevel
125:     x.fillStyle = dark ? 'rgba(255,255,255,.035)' : 'rgba(255,255,255,.12)';
126:     x.fillRect(i * s, j * s, s, 2);
127:     x.fillStyle = 'rgba(0,0,0,.16)';
128:     x.fillRect(i * s, j * s + s - 3, s, 3);
129:   }
130:   // grout lines
131:   x.strokeStyle = 'rgba(20,17,12,.55)'; x.lineWidth = 3;
132:   for (let i = 0; i <= n; i++) {
133:     x.beginPath(); x.moveTo(i * s, 0); x.lineTo(i * s, h); x.stroke();
134:     x.beginPath(); x.moveTo(0, i * s); x.lineTo(w, i * s); x.stroke();
135:   }
136:   grime(x, w, h, 80, 'rgba(25,20,12,');
137:   scratches(x, w, h, 70, 'rgba(255,255,255,.07)');
138:   // scuff marks
139:   for (let i = 0; i < 16; i++) {
140:     x.strokeStyle = `rgba(18,14,9,${.12 + rand() * .2})`;
141:     x.lineWidth = 1 + rand() * 3;
142:     x.beginPath();
143:     const px = rand() * w, py = rand() * h;
144:     x.arc(px, py, 4 + rand() * 22, rand() * 7, rand() * 7);
145:     x.stroke();
146:   }
147:   return finish(c, 4, 4);
148: }
