import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const url = process.argv[2] || 'http://127.0.0.1:3002/';
const out = process.argv[3] || '/tmp/opencode/shots/shot.jpg';
const script = process.argv[4] || '';
const waitMs = parseInt(process.argv[5] || '2500', 10);

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: [
    '--no-sandbox',
    '--enable-gpu',
    '--ignore-gpu-blocklist',
    '--enable-unsafe-webgpu',
    '--use-gl=angle',
    '--use-angle=swiftshader',
    '--disable-dev-shm-usage'
  ]
});
const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto(url, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(waitMs);
if (script) {
  try {
    const r = await page.evaluate(script);
    if (r !== undefined) console.log('EVAL', typeof r === 'string' ? r : JSON.stringify(r));
  } catch (e) { errors.push('EVAL ' + e.message); }
  await page.waitForTimeout(1600);
}
await page.screenshot({ path: out, type: 'jpeg', quality: 82 });
console.log(errors.length ? errors.join('\n') : 'NO ERRORS');
await browser.close();

content.text:
Office is decent but flat, low-poly, and washed out. We need significant visual improvement. Let's verify camera switching bug quickly via script: open cams, switch to 1B, screenshot, check label and feed content. But we know the cause.

Plan the rewrite. I think a robust approach: substantially upgrade world.js (largest file) and add postfx.js. Let's budget effort: maybe 1500-2000 lines of new/changed code. We have plenty of context.

Let me design the new world in detail.

### Rendering pipeline
`src/postfx.js`:
```js
import * as THREE from '../vendor/three.module.min.js';

export class PostFX {
  constructor(renderer) {
    this.renderer = renderer;
    this.enabled = true;
    this.sceneRT = new THREE.WebGLRenderTarget(1,1,{type: THREE.HalfFloatType, format: THREE.RGBAFormat, minFilter: LinearFilter, magFilter: LinearFilter, depthBuffer:true});
    // bloom at quarter res
    ...
    this.quadScene = new THREE.Scene();
    this.quadCam = new THREE.OrthographicCamera(-1,1,1,-1,0,1);
    this.quad = new THREE.Mesh(new THREE.PlaneGeometry(2,2), this.compositeMat);
  }
  ...
  render(scene, camera) {
    renderer.setRenderTarget(sceneRT); renderer.render(scene,camera);
    // bright
    ...
    renderer.setRenderTarget(null); renderer.render(quadScene, quadCam);
  }
}
```
Need bright pass shader with threshold and knee; blur with 9-tap Gaussian separable; composite with ACES approx, saturation/contrast, vignette, grain, chromatic aberration, scanline, letterbox? no.

Because renderer autoClear etc. Use a full-screen triangle? Plane is fine.

Handle resize: RT size = renderer.domElement.width/height (drawing buffer size), bloom half.

Potential WebGL issue: half-float render target without EXT_color_buffer_float on old devices. Use try/catch and fallback to UnsignedByteType. Detect via `renderer.capabilities.isWebGL2` and `renderer.extensions.has('EXT_color_buffer_float')`. r169 is WebGL2 only? r169 supports WebGL2 by default (WebGL1 removed in r163). Half float color buffer is core-ish? Use HalfFloatType.

Tone mapping: set renderer.toneMapping = NoToneMapping and outputColorSpace = SRGBColorSpace, but RT texture colorSpace = LinearSRGBColorSpace. All materials render linear HDR values. Final composite converts to sRGB with pow 1/2.2. Great.

But ShaderMaterial final output: three may inject `#include <colorspace_fragment>`? To be safe, use `gl_FragColor = vec4(pow(color, vec3(1.0/2.2)), 1.0)`. If three also applies sRGB conversion to ShaderMaterial... it does not unless the shader includes it. But three prepends `#define SRGB_TRANSFER`? No. Actually for ShaderMaterial, THREE.WebGLProgram builds the shader by prepending prefix + user's shader; the fragment shader from user is used as-is except includes are resolved. It does run `resolveIncludes`. `#include <colorspace_fragment>` is not in user code. However, for *built-in* materials, three's shaders include it. For our composite ShaderMaterial, we need to add it ourselves. Use `#include <colorspace_fragment>` at end of main? That chunk does `gl_FragColor = linearToOutputTexel( gl_FragColor );`. `linearToOutputTexel` is defined in the prefix based on renderer.outputColorSpace. Since final render is to canvas and outputColorSpace=SRGB, that works. But when rendering the blur passes to RT with ShaderMaterial, those shaders don't include it. So add `#include <colorspace_fragment>` only to composite. Nice, no manual gamma. Use `gl_FragColor` (r169 still supports? In WebGL2 with GLSL3? Three uses GLSL1 by default for ShaderMaterial; gl_FragColor works).

Actually wait: in three r169, WebGLRenderer renders ShaderMaterial with `gl_FragColor` fine.

