Design shader code:

Bright pass:
```glsl
uniform sampler2D tDiffuse; uniform float uThreshold; uniform float uKnee;
varying vec2 vUv;
void main(){
  vec3 c = texture2D(tDiffuse, vUv).rgb;
  float l = max(c.r, max(c.g,c.b));
  float soft = clamp(l - uThreshold + uKnee, 0.0, 2.0*uKnee);
  soft = soft*soft/(4.0*uKnee + 0.0001);
  float contrib = max(soft, l - uThreshold) / max(l, 0.0001);
  gl_FragColor = vec4(c * contrib, 1.0);
}
```
Blur 9-tap:
```glsl
uniform sampler2D tDiffuse; uniform vec2 uDir; // texel * direction
varying vec2 vUv;
void main(){
 vec3 sum = texture2D(tDiffuse,vUv).rgb*0.227027;
 sum += ... weights
}
```
Composite:
```glsl
uniform sampler2D tScene, tBloom;
uniform float uTime,uExposure,uBloom,uVignette,uGrain,uAberration,uDamage,uDesat,uFlash,uBlackout;
varying vec2 vUv;
vec3 aces(vec3 x){...}
float hash(vec2 p){...}
void main(){
  vec2 uv = vUv;
  vec2 c = uv - .5;
  float r2 = dot(c,c);
  // barrel distortion slight
  uv = .5 + c*(1.0 + r2*0.008);
  float ab = uAberration * (0.35 + r2);
  vec2 d = vec2(ab, 0.0) * (uv - .5) * 2.0; // hmm radial
  vec3 col;
  col.r = texture2D(tScene, uv + d).r;
  col.g = texture2D(tScene, uv).g;
  col.b = texture2D(tScene, uv - d).b;
  vec3 bloom = texture2D(tBloom, uv).rgb;
  col += bloom * uBloom;
  col *= uExposure;
  col = aces(col);
  // grade: lift shadows teal, warm highlights
  col = mix(col, col * vec3(1.06,1.0,0.92), 0.35);
  float l = dot(col, vec3(.299,.587,.114));
  col = mix(vec3(l), col, mix(1.0, uDesat, ...));
  // damage red
  col = mix(col, vec3(0.45,0.03,0.02), uDamage*0.6);
  col += uFlash;
  // vignette
  float vig = smoothstep(0.95, 0.25, length(c)*1.1); // compute
  col *= mix(1.0, vig, uVignette);
  // grain
  float g = hash(uv + fract(uTime)*100.0) - 0.5;
  col += g * uGrain;
  col = max(col, 0.0);
  gl_FragColor = vec4(col, 1.0);
  #include <colorspace_fragment>
}
```
Note: `#include <colorspace_fragment>` transforms gl_FragColor; but in r169, the helper name might be `linearToOutputTexel( gl_FragColor )`. It exists in the shader prefix. Good.

