542: function updateHud(force = false) {
543:   if (!game) return;
544:   const pct = Math.round(game.getPowerPct());
545:   const time = game.clockString();
546:   if (force || time !== lastHud.time) { els.hudTime.textContent = time; lastHud.time = time; }
547:   if (force || pct !== lastHud.power) {
548:     els.powerPct.textContent = `${pct}%`;
549:     const on = Math.ceil(pct / 10);
550:     els.powerBars.forEach((b, i) => {
551:       b.className = i < on ? (pct < 12 ? 'crit' : pct < 30 ? 'low' : 'on') : '';
552:     });
553:     lastHud.power = pct;
554:   }
555:   const low = pct <= 18;
556:   if (force || low !== lastHud.low) {
557:     els.power.classList.toggle('critical', low);
558:     document.body.classList.toggle('power-low', low && state === 'playing');
559:     lastHud.low = low;
560:   }
561:   const usage = Math.round(game.usage * 2) / 2;
562:   if (force || usage !== lastHud.usage) {
563:     els.usageBars.forEach((b, i) => {
564:       const v = i + 1;
565:       b.className = usage >= v - .2 ? (usage >= 3 ? 'hot' : 'on') : '';
566:     });
567:     lastHud.usage = usage;
568:   }
569:   const doors = `${game.doors.left ? 1 : 0}${game.doors.right ? 1 : 0}`;
570:   if (force || doors !== lastHud.doors) {
571:     document.querySelector('[data-action="leftDoor"]').classList.toggle('on', game.doors.left);
572:     document.querySelector('[data-action="rightDoor"]').classList.toggle('on', game.doors.right);
573:     lastHud.doors = doors;
574:   }
575:   const lights = `${game.lights.left ? 1 : 0}${game.lights.right ? 1 : 0}`;
576:   if (force || lights !== lastHud.lights) {
577:     const l = document.querySelector('[data-action="leftLight"]');
578:     const r = document.querySelector('[data-action="rightLight"]');
579:     l.classList.toggle('on', game.lights.left);
580:     r.classList.toggle('on', game.lights.right);
581:     l.classList.toggle('light', true);
582:     r.classList.toggle('light', true);
583:     lastHud.lights = lights;
584:   }
585:   if (force || game.camOpen !== lastHud.cam) {
586:     els.camsBtn.classList.toggle('active', game.camOpen);
587:     lastHud.cam = game.camOpen;
588:   }
589: }
