607: function syncWorldCharacters() {
608:   if (!game.ai) return;
609:   for (const side of ['left', 'right']) {
610:     const a = game.aiAtDoor(side);
611:     const type = a ? (a.name === 'freddy' ? 'freddy' : a.name) : null;
612:     if (cornerCache[side] !== type) {
613:       cornerCache[side] = type;
614:       world.setCornerCharacter(side, type);
615:     }
616:   }
617:   const f = game.foxy;
618:   const running = f.running;
619:   if (world._foxyRunning !== running) {
620:     world._foxyRunning = running;
621:     if (!running) world.setFoxyRunning(false);
622:   }
623:   if (running) world.setFoxyRunning(true, clamp(f.runT / 1.75, 0, 1));
624: }
