626: /* ------------------------------------------------------------------ loop */
627: function tick(now) {
628:   requestAnimationFrame(tick);
629:   let dt = (now - last) / 1000;
630:   last = now;
631:   if (dt > .1) dt = .1;
632:   if (dt <= 0) dt = .016;
633: 
634:   // keyboard look
635:   if (state === 'playing' && !game.camOpen) {
636:     let kx = 0, ky = 0;
637:     if (keys.has('arrowleft') || keys.has('a')) kx -= 1;
638:     if (keys.has('arrowright') || keys.has('d')) kx += 1;
639:     if (keys.has('arrowup') || keys.has('w')) ky -= 1;
640:     if (keys.has('arrowdown') || keys.has('s')) ky += 1;
641:     if (kx || ky) {
642:       look.yaw = clamp(look.yaw - kx * dt * 1.35, -1.52, 1.52);
643:       look.pitch = clamp(look.pitch - ky * dt * .75, -.32, .3);
644:       world.targetYaw = look.yaw;
645:       world.targetPitch = look.pitch;
646:     }
647:   }
648: 
649:   if (state === 'playing') {
650:     game.update(dt);
651:     updateHud();
652:     syncWorldCharacters();
653:     for (const side of ['left', 'right']) {
654:       world.setDoor(side, game.doors[side]);
655:       world.setLight(side, game.lights[side]);
656:     }
657:     world.setPower(game.power / 100);
658:     if (game.camOpen) {
659:       feedAcc += dt;
660:       if (feedAcc > .075) {
661:         feedAcc = 0;
662:         feed.draw(game, .075);
663:         setFeedClock();
664:       }
665:     }
666:   } else if (state === 'dead' || state === 'won') {
667:     world.setPower(game.power / 100);
668:   }
669: 
670:   world.update(dt);
671: 
672:   // adaptive quality for sustained mobile framerates
673:   fpsAcc += dt; fpsFrames++;
674:   if (fpsAcc > 2.2) {
675:     const fps = fpsFrames / fpsAcc;
676:     if (fps < 46 && quality > .62) {
677:       quality = Math.max(.62, quality - .11);
678:       world.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75) * quality);
679:       goodWindows = 0;
680:     } else if (fps > 57 && quality < 1) {
681:       goodWindows++;
682:       if (goodWindows >= 3) {
683:         quality = Math.min(1, quality + .08);
684:         world.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75) * quality);
685:         goodWindows = 0;
686:       }
687:     }
688:     fpsAcc = 0; fpsFrames = 0;
689:   }
690: }
