const W = 768, H = 432;

const CAMS = {
  '1A': { name: 'SHOW STAGE' },
  '1B': { name: 'DINING AREA' },
  '1C': { name: 'PIRATE COVE' },
  '2A': { name: 'WEST HALL' },
  '2B': { name: 'WEST HALL CORNER' },
  '3': { name: 'SUPPLY CLOSET' },
  '4A': { name: 'EAST HALL' },
  '4B': { name: 'EAST HALL CORNER' },
  '5': { name: 'BACKSTAGE' }
