/* ---------------- HUD ---------------- */
#hud{position:absolute;inset:0;z-index:10;pointer-events:none;opacity:0;transition:opacity .4s}
#hud.live{opacity:1}
#hud button{pointer-events:auto}
.hud-top{position:absolute;top:calc(10px + var(--safe-t));left:calc(12px + var(--safe-l));right:calc(12px + var(--safe-r));display:flex;align-items:center;justify-content:space-between;gap:10px}
.hud-chip{display:flex;align-items:center;gap:7px;padding:6px 11px;border:1px solid var(--line);background:rgba(6,5,4,.42);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
.hud-chip .lbl{font-size:8px;letter-spacing:.22em;color:#8a7e68}
.hud-chip .val{font-family:'Bebas',sans-serif;font-size:19px;letter-spacing:.08em;color:#e7dcc4;line-height:1}
.time-chip .val{color:#ffc46b;font-size:21px;text-shadow:0 0 16px rgba(255,170,60,.3)}
.hud-brand{font-size:8px;letter-spacing:.4em;color:rgba(210,198,174,.35);white-space:nowrap;flex:1;text-align:center;overflow:hidden;text-overflow:ellipsis}
.hud-hint{position:absolute;top:calc(50px + var(--safe-t));left:50%;transform:translateX(-50%);font-size:9px;letter-spacing:.18em;color:rgba(225,212,186,.55);background:rgba(0,0,0,.35);padding:5px 10px;border:1px solid rgba(255,255,255,.06);white-space:nowrap;transition:opacity .6s;text-shadow:0 1px 4px #000}

