import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--no-sandbox', '--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-gl=angle', '--use-angle=swiftshader', '--disable-dev-shm-usage']
});
const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForSelector('#boot-start:not(.hidden)', { timeout: 30000 });
await page.click('#boot-start');
await page.waitForTimeout(800);
await page.evaluate(() => {
  const f = window.__fnf;
  f.game.unlocked = 7;
  document.querySelectorAll('.night-card').forEach(c => c.classList.remove('locked'));
});
await page.click('[data-night="7"]');
await page.click('#start-night');
await page.waitForTimeout(500);
await page.click('#intro-go');
await page.waitForTimeout(3200);

const snap = async label => ({
  label,
  state: await page.evaluate(() => window.__fnf.getState()),
  night: await page.evaluate(() => window.__fnf.game.night),
  time: await page.evaluate(() => window.__fnf.game.clockString()),
  power: await page.evaluate(() => +window.__fnf.game.power.toFixed(1)),
  signal: await page.evaluate(() => +window.__fnf.game.camSignal.toFixed(1)),
  mb: await page.evaluate(() => +window.__fnf.game.musicBox.toFixed(1)),
  cam: await page.evaluate(() => window.__fnf.game.cam),
  feed: await page.evaluate(() => window.__fnf.feed.cam),
  label: await page.evaluate(() => document.querySelector('#feed-label').textContent)
});
const out = [];
out.push(await snap('after start'));

// doors and lights
await page.keyboard.press('1');
await page.keyboard.press('2');
await page.waitForTimeout(900);
out.push({ doors: await page.evaluate(() => ({ ...window.__fnf.game.doors })), lights: await page.evaluate(() => ({ ...window.__fnf.game.lights })) });
await page.keyboard.press('1');
await page.keyboard.press('2');

// cameras, every selection
await page.click('#cams-btn');
await page.waitForTimeout(700);
out.push(await snap('cams open'));
for (const id of ['2A', '4A', '1C', '3', '5', '6']) {
  await page.click(`[data-cam="${id}"]`);
  await page.waitForTimeout(500);
  out.push(await snap('cam ' + id));
}
// visual switch check: after switching, overlay alpha and feed should change
await page.screenshot({ path: '/tmp/opencode/shots/t_cam6.jpg', type: 'jpeg', quality: 82 });

// wind the music box via mouse hold
await page.evaluate(() => { window.__fnf.game.musicBox = 30; });
const box = await page.locator('#wind-btn').boundingBox();
await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
await page.mouse.down();
await page.waitForTimeout(1800);
out.push({ winding: await page.evaluate(() => ({ mb: +window.__fnf.game.musicBox.toFixed(1), held: window.__fnf.game.windHeld })) });
await page.mouse.up();
await page.waitForTimeout(400);
out.push({ afterWind: await page.evaluate(() => ({ mb: +window.__fnf.game.musicBox.toFixed(1), held: window.__fnf.game.windHeld })) });
await page.screenshot({ path: '/tmp/opencode/shots/t_cam6_wound.jpg', type: 'jpeg', quality: 82 });

// lure on cam 6 (should reject empty) then on 1B
await page.click('#lure-btn');
await page.waitForTimeout(300);
await page.click('[data-cam="1B"]');
await page.click('#lure-btn');
await page.waitForTimeout(400);
out.push({ lure: await page.evaluate(() => ({ cd: +window.__fnf.game.lureCooldown.toFixed(1), toast: document.querySelector('#toast').textContent })) });

// close and reopen on different cam (original bug flow)
await page.click('#cams-close');
await page.waitForTimeout(400);
await page.click('#cams-btn');
await page.waitForTimeout(400);
await page.click('[data-cam="4B"]');
await page.waitForTimeout(700);
out.push(await snap('reopened on 4B'));
await page.screenshot({ path: '/tmp/opencode/shots/t_cam4b.jpg', type: 'jpeg', quality: 82 });
await page.click('#cams-close');

// aux minigame
