await page.waitForTimeout(800);
await page.click('#start-night');
await page.waitForTimeout(500);
await page.click('#intro-go');
await page.waitForTimeout(1500);
await page.click('#cams-btn');
await page.waitForTimeout(400);
await page.click('[data-cam="6"]');
await page.waitForTimeout(600);
await page.evaluate(() => { window.__fnf.game.musicBox = 30; window.__fnf.game.windHeld = true; });
const q = () => page.evaluate(() => ({ mb: +window.__fnf.game.musicBox.toFixed(1), held: window.__fnf.game.windHeld, open: window.__fnf.game.camOpen, cam: window.__fnf.game.cam, t: +window.__fnf.game.nightT.toFixed(2), aux: window.__fnf.game.auxActive }));
console.log('start', await q());
