import { Game } from '/home/runner/work/Fnafv2/Fnafv2/src/game.js';

const audio = new Proxy({ muted: false }, {
  get(t, k) {
    if (k in t) return t[k];
    return () => {};
  }
});

const results = [];
for (let night = 1; night <= 7; night++) {
  let killed = null, won = false, auxes = 0, messages = 0;
  const g = new Game(audio, {
    onDeath: (by, reason) => { killed = { by, reason, t: g.nightT }; },
    onWin: () => { won = true; },
    onAux: active => { if (active) auxes++; },
    onMessage: () => { messages++; },
    onCams: () => {},
    onCamSwitch: () => {},
    onHour: () => {},
    onPowerOut: () => {},
    onReveal: () => {},
    onClearCharacters: () => {},
    onFoxyRun: () => {},
    onMusicBox: () => {},
    onPuppet: () => {},
    onMove: () => {},
    onRetreat: () => {},
    onCorner: () => {},
    onLure: () => {}
  });
  g.startNight(night);
  // stay alive: check at-door and slam, wind music box when low, toggle cams occasionally
  let t = 0, camTimer = 0, auxT = 0;
  const dt = 1 / 30;
  while (t < 330 && !killed && !won) {
    t += dt;
    if (g.auxActive) {
      auxT += dt;
      if (auxT > 1.5) { g.resolveAux(true); auxT = 0; }
    } else {
      for (const side of ['left', 'right']) {
        const a = g.aiAtDoor(side);
        if (a && !g.doors[side]) g.setDoor(side, true);
        if (!a && g.doors[side] && Math.random() < dt * .4) g.setDoor(side, false);
      }
      if (!g.camOpen) {
        camTimer += dt;
        if (camTimer > 9) {
          camTimer = 0;
          g.openCams();
        }
      } else {
        // wind the box if needed, otherwise sweep cameras
        const need = g.musicBox < 55;
        if (need) {
          g.selectCam('6');
          g.windHeld = true;
          g.windMusicBox(dt);
        } else {
          g.windHeld = false;
          const cams = ['1A','1B','1C','2A','2B','3','4A','4B','5'];
          g.selectCam(cams[Math.floor(Math.random() * cams.length)]);
          if (Math.random() < dt * .05) g.lure();
          if (g.camSignal < 25) g.closeCams();
        }
      }
    }
    g.update(dt);
  }
  results.push({
    night, won, killed, power: +g.power.toFixed(1), signal: +g.camSignal.toFixed(0),
    mb: +g.musicBox.toFixed(0), t: +g.nightT.toFixed(0), auxes, messages,
    foxyStage: g.foxy.stage
  });
}
console.log(JSON.stringify(results, null, 1));

