/* ---------------- boot ---------------- */
.boot{z-index:60;background:#050403}
.boot-inner{text-align:center;width:min(420px,86vw)}
.faz-logo{display:flex;flex-direction:column;align-items:center;margin-bottom:34px}
.faz-top{font-family:'Bebas',sans-serif;font-size:clamp(46px,12vw,68px);letter-spacing:.16em;color:#d9cfb8;line-height:.9;text-shadow:0 0 30px rgba(255,180,90,.15)}
.faz-sub{font-size:11px;letter-spacing:.62em;color:#8b7f68;margin-top:10px;padding-left:.62em}
.boot-bar{height:3px;background:rgba(255,255,255,.08);overflow:hidden;margin-bottom:12px}
.boot-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#7d201c,#c7493d,#ffb24a);transition:width .3s ease}
.boot-txt{font-size:10px;letter-spacing:.24em;color:#7c7260}
#boot-start{margin-top:28px}

/* ---------------- menu ---------------- */
.menu{z-index:35;align-items:flex-end;justify-content:center;padding-bottom:calc(18px + var(--safe-b))}
.menu::before{background:linear-gradient(180deg,rgba(0,0,0,.46) 0%,rgba(0,0,0,.10) 30%,rgba(0,0,0,.42) 62%,rgba(0,0,0,.93) 100%)}
.menu-shade{position:absolute;inset:0;background:radial-gradient(ellipse 70% 54% at 50% 30%,transparent,rgba(0,0,0,.55));pointer-events:none}
.menu-inner{position:relative;width:min(880px,100%);text-align:center;padding-top:5vh;max-height:100%;overflow:auto;scrollbar-width:none;touch-action:pan-y}
