import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForSelector('#boot-start:not(.hidden)', { timeout: 30000 });
await page.click('#boot-start');
await page.waitForTimeout(1000);
await page.screenshot({ path: '/tmp/opencode/shots/m_menu.jpg', type: 'jpeg', quality: 82 });
await page.evaluate(() => { window.__fnf.game.unlocked = 7; document.querySelectorAll('.night-card').forEach(c => c.classList.remove('locked')); });
await page.click('[data-night="7"]');
await page.click('#start-night');
await page.waitForTimeout(600);
await page.click('#intro-go');
await page.waitForTimeout(2200);
await page.screenshot({ path: '/tmp/opencode/shots/m_office.jpg', type: 'jpeg', quality: 82 });
await page.click('#cams-btn');
await page.waitForTimeout(1000);
await page.click('[data-cam="6"]');
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/opencode/shots/m_cam6.jpg', type: 'jpeg', quality: 82 });
const info = await page.evaluate(() => {
  const t = document.querySelector('.cam-tablet').getBoundingClientRect();
  const b = document.querySelector('.cam-body').getBoundingClientRect();
  const mb = document.querySelector('#musicbox-panel').getBoundingClientRect();
  return { tablet: [t.width, t.height], body: [b.width, b.height], mb: [mb.width, mb.height], scroll: document.querySelector('.cam-body').scrollHeight };
});
console.log(info);
console.log(errors.length ? errors.join('\n') : 'NO ERRORS');
await browser.close();

